import java.util.*;
/** Educational B-tree of minimum degree 2. Splits full nodes and promotes median keys. */
public class BTreeEducational { BTreeNode root=new BTreeNode(true); static final int T=2; public boolean contains(int k){return search(root,k);} boolean search(BTreeNode x,int k){int i=0; while(i<x.keys.size()&&k>x.keys.get(i))i++; if(i<x.keys.size()&&k==x.keys.get(i))return true; return !x.leaf&&search(x.children.get(i),k);} public void insert(int k){ if(root.keys.size()==2*T-1){BTreeNode s=new BTreeNode(false); s.children.add(root); splitChild(s,0); root=s;} insertNonFull(root,k);} void splitChild(BTreeNode p,int i){BTreeNode y=p.children.get(i), z=new BTreeNode(y.leaf); int median=y.keys.get(T-1); z.keys.add(y.keys.remove(T)); y.keys.remove(T-1); if(!y.leaf){z.children.add(y.children.remove(T)); z.children.add(y.children.remove(T));} p.keys.add(i,median); p.children.add(i+1,z);} void insertNonFull(BTreeNode x,int k){int i=x.keys.size()-1; if(x.leaf){x.keys.add(0); while(i>=0&&k<x.keys.get(i)){x.keys.set(i+1,x.keys.get(i));i--;} x.keys.set(i+1,k);} else {while(i>=0&&k<x.keys.get(i))i--; i++; if(x.children.get(i).keys.size()==2*T-1){splitChild(x,i); if(k>x.keys.get(i))i++;} insertNonFull(x.children.get(i),k);}} public static void main(String[] args){BTreeEducational b=new BTreeEducational(); for(int x:new int[]{8,9,10,11,15,20,17})b.insert(x); System.out.println("B-tree contains 15: "+b.contains(15));}}
